 for(name,n)in[("baseline",112),("candidate",117)]{assert_eq!(read(r.join(format!("native/{name}-core/tests.json")))["passed_tests"].as_array().unwrap().len(),n);}
 let mut t=String::from("# G2 tree scaling on C7a\n\n");writeln!(t,"This dedicated C7a component study has stream calibration **{}**, generic-tree gate **{}**, and prefix-tree gate **{}**. No candidate is adopted. Raw G2 query latency excludes the rest of proving and cannot establish a whole-proof or M5 speedup. The [negative local result](../2026-10-26-g2-prefix-tree/README.md) remains unchanged.\n",a["calibration_passed"],a["generic_gate_passed"],a["prefix_gate_passed"]).unwrap();
 t.push_str("The hypothesis was that roughly22long stream fill jobs may limit high-core scaling while grouped trees expose more independent leaves. Both source snapshots and drivers are unchanged from their local studies, rebuilt for `znver4`. The old-source stream is a calibration control; fresh stream, generic tree and prefix tree share the new executable. This comparison changes target and available physical cores, with no new algorithm or key lookup table.\n\nDedicated c7a.24xlarge,96physical cores without SMT,30GiB container. Two actual fixture B2 queries; workers16/32/64/96 use compact firstN CPU masks. Seven rotated/reversed fresh-process blocks,17timed calls after2primes and1reference setup. All224latency processes finish before six199Hz gated profiles. Preparation/loading,witness solving,reference setup,scalar grouping,other queries,blinding,verification and serialization are excluded. Scalar clone,admission,decomposition,routing,allocations,all reductions,normalization,equality and temporary drops are timed. Allocator atomics are present in both drivers.\n\n## Complete component results\n\nTimes are medians of process medians. Ratios use paired within-block geometric means and need not equal displayed median ratios. All observations remain included.\n\n|Case|Old-source stream ms|Fresh stream ms|Generic tree ms|Prefix tree ms|Generic/fresh|Prefix/fresh|\n|---|---:|---:|---:|---:|---:|---:|\n");
 for shape in ["1x2","2x2"]{for w in [16,32,64,96]{let name=format!("{shape}-w{w}");let c=&a["comparisons"][&name];write!(t,"|{name}|").unwrap();for m in ["frozen","stream","tree","prefix"]{write!(t,"{:.6}|",c["modes"][m]["request_ms"].as_f64().unwrap()).unwrap();}for p in ["tree_stream","prefix_stream"]{write!(t,"{:.6}|",c["pairs"][p]["paired_geomean"].as_f64().unwrap()).unwrap();}t.push('\n');}}
 t.push_str("\n## Memory observations\n\nRequested peak is live caller-layout bytes above prepared inputs. Whole-process RSS includes loading,reference setup and primes; neither is minimum RAM. Forecasts are conservative typed admission bounds.\n\n|Case|Stream / generic / prefix requested peak MiB|Stream / generic / prefix whole-process RSS MiB|\n|---|---:|---:|\n");
 for shape in ["1x2","2x2"]{for w in [16,32,64,96]{let name=format!("{shape}-w{w}");let c=&a["comparisons"][&name]["modes"];write!(t,"|{name}|").unwrap();for metric in ["max_requested_above_inputs_bytes","max_process_RSS_mib"]{for(i,m)in ["stream","tree","prefix"].iter().enumerate(){if i>0{t.push_str(" / ");}let v=c[m][metric].as_f64().unwrap();write!(t,"{:.3}",if metric=="max_requested_above_inputs_bytes"{v/1048576.}else{v}).unwrap();}t.push('|');}t.push('\n');}}
 t.push_str("\n## Qualification\n\nThe frozen calibration requires fresh/old-source stream ratios within factor1.05eachblock and factor1.03pairedmedian for all eight cases. Both tree variants are evaluated independently against both stream controls: primary64and96 must improve with at least4/7wins each;2x2at64and96 must remain within1.02. Workers16/32 are descriptive. There is no minimum gain floor or posthoc variant choice. Failed calibration withholds fine timing qualification.\n\nCalibration failures:\n\n");let cals=a["calibration_failures"].as_array().unwrap();if cals.is_empty(){t.push_str("- None.\n");}for f in cals{writeln!(t,"- {}",f.as_str().unwrap()).unwrap();}
